198	  async abrirComanda(garcomId: number, restaurantId: number, body: AbrirComandaBody, restauranteAberto?: boolean, salaoModo: 'mesas' | 'comandas' | 'ambos' = 'ambos') {
199	    if (!restauranteAberto) {
200	      throw new ForbiddenException('Restaurante fechado — não é possível abrir mesa/comanda');
201	    }
202	    if (salaoModo === 'mesas' && !body.mesa_id) {
203	      throw new BadRequestException('Este restaurante só trabalha com mesas — selecione uma mesa');
204	    }
205	    if (salaoModo === 'comandas' && body.mesa_id) {
206	      throw new BadRequestException('Este restaurante só trabalha com comandas avulsas — não vincule a uma mesa');
207	    }
208	    if (!body.cliente_nome || !body.cliente_telefone) {
209	      throw new BadRequestException('Nome e telefone do cliente são obrigatórios');
210	    }
211	
212	    let mesa: { id: number } | null = null;
213	    if (body.mesa_id) {
214	      const { data } = await this.supabase.client
215	        .from('mesas')
216	        .select('id, status')
217	        .eq('id', body.mesa_id)
218	        .eq('restaurant_id', restaurantId)
219	        .maybeSingle();
220	      if (!data) throw new NotFoundException('Mesa não encontrada');
221	      if (data.status !== 'livre') throw new BadRequestException('Mesa não está livre');
222	      mesa = data;
223	    }
224	
225	    const { data: caixaAberto } = await this.supabase.client
226	      .from('caixas')
227	      .select('id')
228	      .eq('restaurant_id', restaurantId)
229	      .eq('status', 'aberto')
230	      .maybeSingle();
231	
232	    // Numeração sequencial por dia — só pra identificação fácil ("comanda 3"), reinicia
233	    // a cada dia. Não precisa ser à prova de corrida (volume baixo de comandas simultâneas).
234	    const inicioDoDia = new Date();
235	    inicioDoDia.setHours(0, 0, 0, 0);
236	    const { count } = await this.supabase.client
237	      .from('orders')
238	      .select('id', { count: 'exact', head: true })
239	      .eq('restaurant_id', restaurantId)
240	      .eq('canal', 'presencial')
241	      .gte('created_at', inicioDoDia.toISOString());
242	    const numeroComanda = (count ?? 0) + 1;
243	
244	    const { data: comanda, error } = await this.supabase.client
245	      .from('orders')
246	      .insert({
247	        restaurant_id: restaurantId,
248	        canal: 'presencial',
249	        status: 'aberta',
250	        garcom_id: garcomId,
251	        mesa_id: mesa?.id ?? null,
252	        cliente_mesa_nome: body.cliente_nome,
253	        cliente_mesa_telefone: body.cliente_telefone,
254	        total: 0,
255	        caixa_id: caixaAberto?.id ?? null,
256	        numero_comanda: numeroComanda,
257	      })
258	      .select()
259	      .single();
260	    if (error) throw error;
261	
262	    if (mesa) {
263	      await this.supabase.client.from('mesas').update({ status: 'ocupada' }).eq('id', mesa.id);
264	    }
265	
266	    return comanda;
267	  }
