315	  async obterComanda(comandaId: number, garcomId: number) {
316	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
317	
318	    const { data: itens, error } = await this.supabase.client
319	      .from('order_items')
320	      .select('id, product_id, quantity, unit_price, observacao, status, enviado_em, products(name, image_url)')
321	      .eq('order_id', comandaId)
322	      .order('id', { ascending: true });
323	    if (error) throw error;
324	
325	    const { data: pagamentos } = await this.supabase.client
326	      .from('comanda_pagamentos')
327	      .select('id, valor, forma_pagamento, origem, criado_em')
328	      .eq('order_id', comandaId)
329	      .order('criado_em', { ascending: true });
330	    const saldo = await this.saldoDevedor(comandaId);
331	
332	    // Sugestão de gorjeta exibida pro garçom/cliente antes do fechamento — informativa,
333	    // o valor de fato lançado é o que o caixa confirma no PDV (pode ajustar).
334	    const { data: restaurante } = await this.supabase.client
335	      .from('restaurants')
336	      .select('gorjeta_percentual')
337	      .eq('id', comanda.restaurant_id)
338	      .maybeSingle();
339	    const percentual = restaurante?.gorjeta_percentual ?? 0;
340	    const subtotalItens = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
341	    const gorjeta_sugestao = { percentual, valor_sugerido: parseFloat(((subtotalItens * percentual) / 100).toFixed(2)) };
342	
343	    return { ...comanda, itens, pagamentos: pagamentos ?? [], saldo, gorjeta_sugestao };
344	  }
