346	  async adicionarItens(comandaId: number, garcomId: number, itens: ItemComandaBody[]) {
347	    if (!itens?.length) throw new BadRequestException('Informe ao menos 1 item');
348	
349	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
350	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda não está aberta');
351	
352	    const prodIds = itens.map((i) => i.product_id);
353	    const { data: produtos, error: errProd } = await this.supabase.client
354	      .from('products')
355	      .select('id, price, is_active')
356	      .in('id', prodIds);
357	    if (errProd) throw errProd;
358	
359	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
360	    for (const item of itens) {
361	      const prod = prodMap[item.product_id];
362	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
363	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
364	    }
365	
366	    const { error } = await this.supabase.client.from('order_items').insert(
367	      itens.map((i) => ({
368	        order_id: comandaId,
369	        product_id: i.product_id,
370	        quantity: i.quantity,
371	        unit_price: prodMap[i.product_id].price,
372	        observacao: i.observacao?.trim() || null,
373	        status: 'pendente',
374	      })),
375	    );
376	    if (error) throw error;
377	
378	    await this.recalcularTotal(comandaId);
379	    return this.obterComanda(comandaId, garcomId);
380	  }
