468	  // Marcador seguro pra "negrito desligado" — o comando ESC/POS real (ESC E 0x00) tem um
469	  // byte NUL, que o Postgres TEXT não aceita (quebra o insert). Guardamos esse marcador no
470	  // banco e só trocamos pelo byte real em printers.py, na hora de mandar pra impressora.
471	  private static readonly MARCADOR_NEGRITO_OFF = '\x01BOLDOFF\x01';
472	
473	  // Impressora térmica não usa a mesma codepage do texto enviado (cp850) — byte de acento
474	  // acaba sendo lido como início de caractere multi-byte, "comendo" a letra seguinte junto
475	  // (ex.: "Pão com Queijo" saía "P com Queijo"). Solução robusta e independente de firmware:
476	  // tira o acento antes de imprimir, garantindo ASCII puro em qualquer impressora.
477	  private removerAcentos(texto: string): string {
478	    return texto.normalize('NFD').replace(new RegExp('[\\u0300-\\u036f]', 'g'), '');
479	  }
