481	  formatarTicketTexto(
482	    setor: string,
483	    comanda: {
484	      mesas?: { numero: number; nome: string | null } | null;
485	      cliente_mesa_nome?: string | null;
486	      cliente_mesa_telefone?: string | null;
487	      garcons?: { nome: string } | null;
488	    },
489	    itens: { product_name?: string; quantity: number; description?: string | null; observacao?: string | null }[],
490	  ): string {
491	    // ESC/POS: fonte dupla (altura+largura) pra facilitar leitura em impressora térmica
492	    // (pedido de acessibilidade — usuário com baixa visão lê o ticket na cozinha/bar).
493	    // Nota: não dá pra mandar um byte 0x00 (reset de fonte) — Postgres TEXT não aceita
494	    // NUL embutido, o insert falha silenciosamente. Cada ticket novo já reinicializa a
495	    // impressora (ESC_INIT = ESC @) então não precisa resetar a fonte no fim deste.
496	    const ESC_INIT = '\x1b\x40';
497	    const FONTE_DUPLA = '\x1d\x21\x11';
498	    const NEGRITO_ON = '\x1b\x45\x01';
499	    const NEGRITO_OFF = SalaoService.MARCADOR_NEGRITO_OFF;
500	
501	    const linhas: string[] = [];
502	    linhas.push(ESC_INIT + FONTE_DUPLA);
503	    linhas.push(this.removerAcentos(setor.toUpperCase()));
504	    if (comanda.mesas) {
505	      linhas.push(
506	        this.removerAcentos(`Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}`),
507	      );
508	    }
509	    if (comanda.garcons?.nome) linhas.push(this.removerAcentos(`Garcom: ${comanda.garcons.nome}`));
510	    if (comanda.cliente_mesa_nome) linhas.push(this.removerAcentos(`Cliente: ${comanda.cliente_mesa_nome}`));
511	    if (comanda.cliente_mesa_telefone) linhas.push(`Whatsapp: ${comanda.cliente_mesa_telefone}`);
512	    linhas.push(new Date().toLocaleString('pt-BR'));
513	    linhas.push('--------------------------------');
514	    itens.forEach((item, idx) => {
515	      linhas.push(`${NEGRITO_ON}${this.removerAcentos(item.product_name ?? 'Produto')}${NEGRITO_OFF}`);
516	      linhas.push(`${NEGRITO_ON}Qtd: ${item.quantity}${NEGRITO_OFF}`);
517	      if (item.description) linhas.push(this.removerAcentos(`Descricao: ${item.description}`));
518	      if (item.observacao) linhas.push(this.removerAcentos(`Obs: ${item.observacao}`));
519	      if (idx < itens.length - 1) {
520	        linhas.push('');
521	        linhas.push('---------------');
522	      }
523	    });
524	    linhas.push('--------------------------------');
525	    return linhas.join('\n');
526	  }
