528	  // Recibo do cliente (pagamento final / venda direta) — mesma ideia do ticket de setor,
529	  // mas com preço/subtotal/desconto/gorjeta/total/forma de pagamento, pra impressora
530	  // configurada em Config > "Impressora do recibo" (ver restaurante.service.ts).
531	  formatarReciboTexto(
532	    restauranteNome: string,
533	    comanda: {
534	      mesas?: { numero: number; nome: string | null } | null;
535	      mesa_id?: number | null;
536	      cliente_mesa_nome?: string | null;
537	    },
538	    itens: { product_name?: string; quantity: number; unit_price?: number }[],
539	    valores: {
540	      subtotal: number;
541	      desconto?: number;
542	      acrescimo?: number;
543	      gorjeta?: number;
544	      taxaCartao?: number;
545	      total: number;
546	      formaPagamento: string;
547	      trocoDado?: number;
548	    },
549	    pagamentos?: { valor: number; forma_pagamento: string; origem: string }[],
550	  ): string {
551	    const fmt = (v?: number) => (v ?? 0).toFixed(2).replace('.', ',');
552	    const PAGAMENTO_LABEL: Record<string, string> = { pix: 'PIX', credit_card: 'Cartao', debit_card: 'Debito', cash: 'Dinheiro' };
553	    const NEGRITO_ON = '\x1b\x45\x01';
554	    const NEGRITO_OFF = SalaoService.MARCADOR_NEGRITO_OFF;
555	
556	    const linhas: string[] = [];
557	    linhas.push('\x1b\x40');
558	    linhas.push(this.removerAcentos(restauranteNome ?? 'RESTAURANTE'));
559	    linhas.push('RECIBO DE PAGAMENTO');
560	    linhas.push(comanda.mesa_id ? this.removerAcentos(`Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}`) : 'Venda balcao');
561	    if (comanda.cliente_mesa_nome) linhas.push(this.removerAcentos(comanda.cliente_mesa_nome));
562	    linhas.push(new Date().toLocaleString('pt-BR'));
563	    linhas.push('--------------------------------');
564	    const LARGURA_LINHA = 32;
565	    for (const item of itens) {
566	      const qtd = `${item.quantity}x`.padEnd(4);
567	      const valorTxt = `R$ ${fmt((item.quantity ?? 0) * (item.unit_price ?? 0))}`;
568	      const espacoDesc = Math.max(LARGURA_LINHA - qtd.length - valorTxt.length, 1);
569	      const desc = this.removerAcentos(item.product_name ?? 'Produto').slice(0, espacoDesc).padEnd(espacoDesc);
570	      linhas.push(`${qtd}${desc}${valorTxt}`);
571	    }
572	    linhas.push('--------------------------------');
573	    linhas.push(`Subtotal: R$ ${fmt(valores.subtotal)}`);
574	    if (valores.desconto) linhas.push(`Desconto: - R$ ${fmt(valores.desconto)}`);
575	    if (valores.acrescimo) linhas.push(`Acrescimo: + R$ ${fmt(valores.acrescimo)}`);
576	    if (valores.gorjeta) linhas.push(`Gorjeta: R$ ${fmt(valores.gorjeta)}`);
577	    if (valores.taxaCartao) linhas.push(`Taxa cartao: + R$ ${fmt(valores.taxaCartao)}`);
578	    linhas.push(`${NEGRITO_ON}TOTAL: R$ ${fmt(valores.total)}${NEGRITO_OFF}`);
579	    if (pagamentos?.length) {
580	      linhas.push('--------------------------------');
581	      linhas.push('Pagamentos:');
582	      for (const p of pagamentos) {
583	        const origemLabel = p.origem === 'garcom' ? 'garcom' : 'caixa';
584	        linhas.push(`${PAGAMENTO_LABEL[p.forma_pagamento] ?? p.forma_pagamento} (${origemLabel}): R$ ${fmt(p.valor)}`);
585	      }
586	    } else {
587	      linhas.push(`Pagamento: ${PAGAMENTO_LABEL[valores.formaPagamento] ?? valores.formaPagamento}`);
588	    }
589	    if (valores.trocoDado) linhas.push(`Troco: R$ ${fmt(valores.trocoDado)}`);
590	    linhas.push('--------------------------------');
591	    linhas.push('Obrigado pela preferencia!');
592	    return linhas.join('\n');
593	  }
