598	  async imprimirReciboSeConfigurado(
599	    restaurantId: number,
600	    comanda: any,
601	    itens: { product_name?: string; quantity: number; unit_price?: number }[],
602	    valores: { subtotal: number; desconto?: number; acrescimo?: number; gorjeta?: number; taxaCartao?: number; total: number; formaPagamento: string; trocoDado?: number },
603	    pagamentos?: { valor: number; forma_pagamento: string; origem: string }[],
604	  ): Promise<{ via: 'agente' } | { via: 'navegador' }> {
605	    const { data: restaurante } = await this.supabase.client
606	      .from('restaurants')
607	      .select('name, recibo_impressora_id')
608	      .eq('id', restaurantId)
609	      .maybeSingle();
610	    const impressoraId = (restaurante as any)?.recibo_impressora_id;
611	    if (!impressoraId) return { via: 'navegador' };
612	
613	    const { data: impressora } = await this.supabase.client
614	      .from('impressoras')
615	      .select('id, nome_sistema')
616	      .eq('id', impressoraId)
617	      .eq('restaurant_id', restaurantId)
618	      .maybeSingle();
619	    if (!impressora?.nome_sistema) return { via: 'navegador' };
620	
621	    const conteudo = this.formatarReciboTexto((restaurante as any)?.name, comanda, itens, valores, pagamentos);
622	    await this.supabase.client.from('impressao_jobs').insert({
623	      restaurant_id: restaurantId,
624	      impressora_id: impressoraId,
625	      conteudo,
626	    });
627	    return { via: 'agente' };
628	  }
629	
630	  // Ticket de conferência pedido pelo caixa antes de fechar a conta — `valores` vem
631	  // preenchido com o que está na tela (desconto/acréscimo/gorjeta/taxa/forma). O
632	  // cliente (QR, sem login) só pode solicitar conferência, nunca gerar isso direto.
633	  formatarConferenciaTexto(
634	    restauranteNome: string,
635	    comanda: { mesas?: { numero: number; nome: string | null } | null; cliente_mesa_nome?: string | null },
636	    itens: { product_name?: string; quantity: number; unit_price?: number }[],
637	    valores: { desconto?: number; acrescimo?: number; gorjeta?: number; taxaCartao?: number; formaPagamento?: string },
638	  ): string {
639	    const fmt = (v?: number) => (v ?? 0).toFixed(2).replace('.', ',');
640	    const NEGRITO_ON = '\x1b\x45\x01';
641	    const NEGRITO_OFF = SalaoService.MARCADOR_NEGRITO_OFF;
642	    const PAGAMENTO_LABEL: Record<string, string> = { pix: 'PIX', credit_card: 'Cartao', debit_card: 'Debito', cash: 'Dinheiro' };
643	
644	    const linhas: string[] = [];
645	    linhas.push('\x1b\x40');
646	    linhas.push(this.removerAcentos(restauranteNome ?? 'RESTAURANTE'));
647	    linhas.push('CONFERENCIA - NAO E RECIBO FISCAL');
648	    if (comanda.mesas) {
649	      linhas.push(this.removerAcentos(`Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}`));
650	    }
651	    if (comanda.cliente_mesa_nome) linhas.push(this.removerAcentos(comanda.cliente_mesa_nome));
652	    linhas.push(new Date().toLocaleString('pt-BR'));
653	    linhas.push('--------------------------------');
654	    let subtotal = 0;
655	    for (const item of itens) {
656	      const totalItem = (item.quantity ?? 0) * (item.unit_price ?? 0);
657	      subtotal += totalItem;
658	      linhas.push(this.removerAcentos(`${item.quantity}x ${item.product_name ?? 'Produto'}`));
659	      linhas.push(`R$ ${fmt(totalItem)}`);
660	    }
661	    linhas.push('--------------------------------');
662	    const { desconto = 0, acrescimo = 0, gorjeta = 0, taxaCartao = 0, formaPagamento } = valores;
663	    const total = subtotal - desconto + acrescimo + gorjeta + taxaCartao;
664	    linhas.push(`Subtotal: R$ ${fmt(subtotal)}`);
665	    if (desconto) linhas.push(`Desconto: - R$ ${fmt(desconto)}`);
666	    if (acrescimo) linhas.push(`Acrescimo: + R$ ${fmt(acrescimo)}`);
667	    if (gorjeta) linhas.push(`Gorjeta: + R$ ${fmt(gorjeta)}`);
668	    if (taxaCartao) linhas.push(`Taxa cartao: + R$ ${fmt(taxaCartao)}`);
669	    linhas.push(`${NEGRITO_ON}TOTAL: R$ ${fmt(total)}${NEGRITO_OFF}`);
670	    if (formaPagamento) linhas.push(`Forma de pagamento: ${PAGAMENTO_LABEL[formaPagamento] ?? formaPagamento}`);
671	    linhas.push('--------------------------------');
672	    linhas.push('Peca ao garcom pra fechar a conta');
673	    return linhas.join('\n');
674	  }
675	
676	  // Cliente só pode SOLICITAR conferência (sem login, tela pública) — nunca mandar
677	  // nada pra impressão direto. Só marca o pedido; quem imprime de fato é o caixa,
678	  // via imprimirConferencia do PDV (que também limpa esse campo ao atender).
679	  async solicitarConferencia(token: string): Promise<{ ok: true } | { ok: false; motivo: 'nao_encontrada' }> {
680	    const { data: comanda } = await this.supabase.client
681	      .from('orders')
682	      .select('id')
683	      .eq('tracking_token', token)
684	      .eq('canal', 'presencial')
685	      .in('status', ['aberta', 'fechada_garcom'])
686	      .maybeSingle();
687	    if (!comanda) return { ok: false, motivo: 'nao_encontrada' };
688	
689	    const { error } = await this.supabase.client
690	      .from('orders')
691	      .update({ conferencia_solicitada_em: new Date().toISOString() })
692	      .eq('id', comanda.id)
693	      .is('conferencia_solicitada_em', null);
694	    if (error) throw error;
695	    return { ok: true };
696	  }
697	
698	  async enviarItens(comandaId: number, garcomId: number) {
699	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
700	    return this.processarEnvioPendentes(comandaId, comanda);
701	  }
702	
703	  // Mesmo processamento de envio/impressão, chamado pelo lado do estabelecimento (PDV) quando
704	  // o dono/caixa inclui um item direto na comanda — não precisa do garçom "enviar" separado.
705	  async enviarItensComoRestaurante(comandaId: number, comanda: any) {
706	    return this.processarEnvioPendentes(comandaId, comanda);
707	  }
708	
709	  private async processarEnvioPendentes(comandaId: number, comanda: any) {
710	    const { data: pendentes, error } = await this.supabase.client
711	      .from('order_items')
712	      .select('id, product_id, quantity, observacao, products(name, description, impressora_id, impressoras(id, nome, setor, nome_sistema))')
713	      .eq('order_id', comandaId)
714	      .eq('status', 'pendente');
715	    if (error) throw error;
716	    if (!pendentes?.length) return { grupos: [] };
717	
718	    const agora = new Date().toISOString();
719	    await this.supabase.client
720	      .from('order_items')
721	      .update({ status: 'enviado', enviado_em: agora })
722	      .in(
723	        'id',
724	        pendentes.map((p: any) => p.id),
725	      );
726	
727	    for (const item of pendentes as any[]) {
728	      const impressoraId = item.products?.impressora_id ?? null;
729	      if (impressoraId) {
730	        await this.supabase.client.from('order_items').update({ impressora_id: impressoraId }).eq('id', item.id);
731	      }
732	    }
733	
734	    const grupos = new Map<string, { setor: string; impressora_id: number | null; impressora_nome: string | null; nome_sistema: string | null; itens: any[] }>();
735	    for (const item of pendentes as any[]) {
736	      const impressora = item.products?.impressoras;
737	      const chave = impressora?.id ? String(impressora.id) : 'sem-impressora';
738	      if (!grupos.has(chave)) {
739	        grupos.set(chave, {
740	          setor: impressora?.setor ?? 'Sem setor',
741	          impressora_id: impressora?.id ?? null,
742	          impressora_nome: impressora?.nome ?? null,
743	          nome_sistema: impressora?.nome_sistema ?? null,
744	          itens: [],
745	        });
746	      }
747	      grupos.get(chave)!.itens.push({
748	        product_name: item.products?.name,
749	        description: item.products?.description,
750	        quantity: item.quantity,
751	        observacao: item.observacao,
752	      });
753	    }
754	
755	    // Impressoras com agente local pareado (nome_sistema preenchido) viram um job de
756	    // impressão na fila — o agente Python puxa e imprime. As demais continuam caindo
757	    // no fallback de window.print() no navegador (grupos devolvidos pro frontend).
758	    const gruposParaNavegador: any[] = [];
759	    for (const grupo of grupos.values()) {
760	      if (grupo.nome_sistema && grupo.impressora_id) {
761	        const conteudo = this.formatarTicketTexto(grupo.setor, comanda as any, grupo.itens);
762	        const { error: errJob } = await this.supabase.client.from('impressao_jobs').insert({
763	          restaurant_id: comanda.restaurant_id,
764	          impressora_id: grupo.impressora_id,
765	          conteudo,
766	        });
767	        if (errJob) throw errJob;
768	      } else {
769	        gruposParaNavegador.push({ setor: grupo.setor, impressora_nome: grupo.impressora_nome, itens: grupo.itens });
770	      }
771	    }
772	
773	    return { grupos: gruposParaNavegador };
774	  }
775	
776	  // Reimpressão manual pedida na tela de KDS por setor — regera o ticket do grupo
777	  // (comanda + itens já enviados pra essa impressora) e reenvia pro mesmo destino
778	  // de sempre (fila do agente local ou fallback pro navegador).
779	  // Reimpressão por item (não por comanda inteira) — pedido explícito: cada prato tem
780	  // seu próprio ticket, imprimir de novo não deve reimprimir os outros itens da mesa junto.
781	  async reimprimirItem(itemId: number, restaurantId: number) {
782	    const { data: item } = await this.supabase.client
783	      .from('order_items')
784	      .select('id, quantity, observacao, impressora_id, order_id, products(name, description), orders(id, restaurant_id, mesas(numero, nome), cliente_mesa_nome, cliente_mesa_telefone, garcons(nome))')
785	      .eq('id', itemId)
786	      .maybeSingle();
787	    if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
788	      throw new NotFoundException('Item não encontrado');
789	    }
790	    if (!item.impressora_id) throw new BadRequestException('Item sem impressora associada');
791	
792	    const { data: impressora } = await this.supabase.client
793	      .from('impressoras')
794	      .select('id, nome, setor, nome_sistema')
795	      .eq('id', item.impressora_id)
796	      .eq('restaurant_id', restaurantId)
797	      .maybeSingle();
798	    if (!impressora) throw new NotFoundException('Impressora não encontrada');
799	
800	    const itensFormatados = [{
801	      product_name: (item as any).products?.name,
802	      description: (item as any).products?.description,
803	      quantity: item.quantity,
804	      observacao: item.observacao,
805	    }];
806	    const conteudo = this.formatarTicketTexto((impressora as any).setor, (item as any).orders, itensFormatados);
807	
808	    if ((impressora as any).nome_sistema) {
809	      const { error } = await this.supabase.client.from('impressao_jobs').insert({
810	        restaurant_id: restaurantId,
811	        impressora_id: item.impressora_id,
812	        conteudo,
813	      });
814	      if (error) throw error;
815	      return { ok: true, via: 'agente' };
816	    }
817	
818	    return { ok: true, via: 'navegador', setor: (impressora as any).setor, impressora_nome: (impressora as any).nome, itens: itensFormatados };
819	  }
820	
821	  async fecharComanda(comandaId: number, garcomId: number, formaPagamento: string) {
822	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
823	
824	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
825	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda já foi fechada');
826	
827	    const { data: itens } = await this.supabase.client.from('order_items').select('id').eq('order_id', comandaId);
828	    if (!itens?.length) throw new BadRequestException('Comanda sem itens não pode ser fechada');
829	
830	    const { error } = await this.supabase.client
831	      .from('orders')
832	      .update({ status: 'fechada_garcom', payment_method: formaPagamento })
833	      .eq('id', comandaId);
834	    if (error) throw error;
835	
836	    if (comanda.mesa_id) {
837	      await this.supabase.client.from('mesas').update({ status: 'aguardando_pagamento' }).eq('id', comanda.mesa_id);
838	    }
839	
840	    return { ok: true };
841	  }
842	}
