1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { SalaoService } from './salao.service';
4	import type { ItemComandaBody } from './salao.service';
5	
6	// PDV do caixa (lado estabelecimento): ações de cancelar/desconto/acréscimo/pagar
7	// são exclusivas do dono (RestaurantOwnerGuard) — o garçom nunca tem acesso a
8	// essas rotas (ver salao.controller.ts, que só cobre abrir/adicionar/enviar/fechar).
9	@Injectable()
10	export class SalaoPdvService {
11	  constructor(
12	    private supabase: SupabaseService,
13	    private salaoService: SalaoService,
14	  ) {}
15	
16	  async mesas(restaurantId: number) {
17	    const { data: mesas, error } = await this.supabase.client
18	      .from('mesas')
19	      .select('id, numero, nome, status')
20	      .eq('restaurant_id', restaurantId)
21	      .order('numero', { ascending: true });
22	    if (error) throw error;
23	
24	    const { data: comandas } = await this.supabase.client
25	      .from('orders')
26	      .select('id, mesa_id, garcom_id, total, status, numero_comanda, cliente_mesa_nome, garcons(nome), aberto_por_nome')
27	      .eq('restaurant_id', restaurantId)
28	      .eq('canal', 'presencial')
29	      .in('status', ['aberta', 'fechada_garcom'])
30	      .not('mesa_id', 'is', null);
31	
32	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
33	
34	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
35	  }
36	
37	  // Bloqueia uma mesa livre (reserva, manutenção...) — fica indisponível pro garçom
38	  // até ser desbloqueada, sem precisar de comanda aberta nela.
39	  async bloquearMesa(mesaId: number, restaurantId: number) {
40	    const { data: mesa } = await this.supabase.client
41	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
42	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
43	    if (mesa.status !== 'livre') throw new BadRequestException('Só é possível bloquear uma mesa livre');
44	
45	    const { error } = await this.supabase.client.from('mesas').update({ status: 'bloqueada' }).eq('id', mesaId);
46	    if (error) throw error;
47	    return { ok: true };
48	  }
49	
50	  async desbloquearMesa(mesaId: number, restaurantId: number) {
51	    const { data: mesa } = await this.supabase.client
52	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
53	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
54	    if (mesa.status !== 'bloqueada') throw new BadRequestException('Mesa não está bloqueada');
55	
56	    const { error } = await this.supabase.client.from('mesas').update({ status: 'livre' }).eq('id', mesaId);
57	    if (error) throw error;
58	    return { ok: true };
59	  }
60	
61	  // Estabelecimento abre mesa/comanda direto (sem garçom envolvido) — mesma regra de
62	  // salao_modo e obrigatoriedade de nome/telefone do cliente do lado do garçom.
63	  // Guarda o primeiro nome de quem tava logado (aberto_por_nome) pro card da mesa
64	  // mostrar "Caixa: nome" pro garçom e pro próprio estabelecimento.
65	  async abrirComanda(restaurantId: number, userId: string, body: { mesa_id?: number; cliente_nome: string; cliente_telefone: string }) {
66	    if (!body.cliente_nome || !body.cliente_telefone) {
67	      throw new BadRequestException('Nome e telefone do cliente são obrigatórios');
68	    }
69	
70	    const { data: restaurante } = await this.supabase.client
71	      .from('restaurants').select('salao_modo').eq('id', restaurantId).maybeSingle();
72	    const salaoModo = (restaurante as any)?.salao_modo ?? 'ambos';
73	    if (salaoModo === 'mesas' && !body.mesa_id) {
74	      throw new BadRequestException('Este restaurante só trabalha com mesas — selecione uma mesa');
75	    }
76	    if (salaoModo === 'comandas' && body.mesa_id) {
77	      throw new BadRequestException('Este restaurante só trabalha com comandas avulsas — não vincule a uma mesa');
78	    }
79	
80	    let mesa: { id: number } | null = null;
81	    if (body.mesa_id) {
82	      const { data } = await this.supabase.client
83	        .from('mesas').select('id, status').eq('id', body.mesa_id).eq('restaurant_id', restaurantId).maybeSingle();
84	      if (!data) throw new NotFoundException('Mesa não encontrada');
85	      if (data.status !== 'livre') throw new BadRequestException('Mesa não está livre');
86	      mesa = data;
87	    }
88	
89	    const { data: caixaAberto } = await this.supabase.client
90	      .from('caixas').select('id').eq('restaurant_id', restaurantId).eq('status', 'aberto').maybeSingle();
91	
92	    const { data: userData } = await this.supabase.client.auth.admin.getUserById(userId);
93	    const nomeCompleto = userData?.user?.user_metadata?.name as string | undefined;
94	    const abertoPorNome = nomeCompleto?.trim().split(' ')[0] || null;
95	
96	    const inicioDoDia = new Date();
97	    inicioDoDia.setHours(0, 0, 0, 0);
98	    const { count } = await this.supabase.client
99	      .from('orders').select('id', { count: 'exact', head: true })
100	      .eq('restaurant_id', restaurantId).eq('canal', 'presencial').gte('created_at', inicioDoDia.toISOString());
101	    const numeroComanda = (count ?? 0) + 1;
102	
103	    const { data: comanda, error } = await this.supabase.client
104	      .from('orders')
105	      .insert({
106	        restaurant_id: restaurantId,
107	        canal: 'presencial',
108	        status: 'aberta',
109	        mesa_id: mesa?.id ?? null,
110	        cliente_mesa_nome: body.cliente_nome,
111	        cliente_mesa_telefone: body.cliente_telefone,
112	        total: 0,
113	        caixa_id: caixaAberto?.id ?? null,
114	        numero_comanda: numeroComanda,
115	        aberto_por_nome: abertoPorNome,
116	      })
117	      .select('id')
118	      .single();
119	    if (error) throw error;
120	
121	    if (mesa) {
122	      await this.supabase.client.from('mesas').update({ status: 'ocupada' }).eq('id', mesa.id);
123	    }
124	
125	    return this.comandaDetalhe(comanda.id, restaurantId);
126	  }
127	
128	  async comandasAbertas(restaurantId: number) {
129	    const { data, error } = await this.supabase.client
130	      .from('orders')
131	      .select('id, mesa_id, cliente_mesa_nome, cliente_mesa_telefone, total, status, payment_method, numero_comanda, created_at, mesas(numero, nome), garcons(nome), aberto_por_nome')
132	      .eq('restaurant_id', restaurantId)
133	      .eq('canal', 'presencial')
134	      .in('status', ['aberta', 'fechada_garcom'])
135	      .order('created_at', { ascending: false });
136	    if (error) throw error;
137	    return data;
138	  }
139	
