            {FILTROS.slice(1).map((s) => (
              <option key={s} value={s}>{STATUS_LABELS[s]?.label}</option>
            ))}
          </select>
          <button onClick={carregar} className="px-4 py-2 text-sm bg-gray-100 hover:bg-gray-200 rounded-lg">
